import {makeDigitalGift} from './digital-export.js';
import {downloadFile} from './experience.js';
import {mediaSize} from './media-compression.js';
export function initCloudDelivery({billing,getData,getAudio,getState,onRestore,onPublished=()=>{},prepare=async()=>{},toast}){
 const panel=document.createElement('section');panel.className='cloud-delivery';panel.innerHTML='<h3>Um link para o seu mimo.</h3><p>Publique o presente com as fotos e o áudio. Quem recebe abre pelo link, sem precisar de uma conta. Você também pode guardar a cópia para compartilhar como arquivo.</p><p>O presente publicado pode ter até 40 MB. O editor tenta otimizar fotos e áudio para facilitar o envio.</p><p class="cloud-environment"></p><button type="button" class="button primary cloud-publish">Publicar e criar meu link</button><p class="cloud-status" role="status"></p><div class="cloud-result" hidden><label>Link do presente<input class="cloud-link" readonly></label><div class="cloud-actions"><button type="button" class="cloud-copy">Copiar link</button><a class="cloud-open" target="_blank" rel="noopener noreferrer">Abrir como quem recebe</a></div><canvas class="cloud-qr" width="220" height="220" role="img" aria-label="QR Code do presente publicado"></canvas><button type="button" class="cloud-qr-save" disabled>Baixar QR Code</button><p class="cloud-qr-status" role="status" tabindex="-1"></p><button type="button" class="cloud-qr-retry" hidden>Tentar gerar QR Code novamente</button><p class="cloud-expiry"></p></div><details class="cloud-access"><summary>Guardar acesso ou voltar em outro aparelho</summary><p class="cloud-access-description">O arquivo de acesso permite editar e atualizar a compra. Guarde só para você. Para presentear alguém, envie o link do mimo ou o arquivo do presente.</p><button type="button" class="cloud-save-access">Guardar meu acesso</button><label>Recuperar uma compra<input class="cloud-restore-access" type="file" accept="application/json,.json"></label><label class="cloud-purchase-label" hidden>Compra<select class="cloud-purchase-select"></select></label><button type="button" class="cloud-edit-published" hidden>Abrir a versão publicada para editar</button></details><details class="cloud-guests" hidden><summary>Convites por pessoa e confirmações</summary><p>Crie um link individual para cada convidado. A resposta fica salva e aparece aqui. Os novos links ficam disponíveis ao voltar pela sua conta, inclusive em outro aparelho.</p><form><label>Nome do convidado<input name="guestName" maxlength="80" required></label><label>Pessoas neste convite<input name="guestCount" type="number" min="1" max="10" value="1" required></label><button type="submit">Criar convite individual</button></form><button type="button" class="cloud-import-guests">Gerar links da minha lista de convidados</button><button type="button" class="cloud-refresh-guests">Atualizar confirmações</button><div class="cloud-guest-list"></div></details>';
 panel.hidden=true;document.querySelector('.digital-delivery').after(panel);const $=selector=>panel.querySelector(selector),status=$('.cloud-status');let busy=false,chosen='',renderedDraft='',guestView='',guestRenderEpoch=0;
 function current(){return billing.get(chosen)||billing.find();}
 let restoreEpoch=0,restoreView='',restoreViewEpoch=0;
 const restoreAccount=()=>JSON.stringify([billing.config.mode,billing.account?.email||'',billing.account?.authenticated===true]);
 const restoreContext=()=>JSON.stringify([getState().draftId,getState().format,getState().purchaseId||'',chosen,current()?.id||'',restoreAccount()]);
 function trackRestoreContext(){const next=restoreContext();if(next!==restoreView){restoreView=next;restoreViewEpoch++;}}
 function beginRestore(){trackRestoreContext();const own=++restoreEpoch,view=restoreViewEpoch,started=restoreContext(),account=restoreAccount();return{isCurrent:()=>own===restoreEpoch&&view===restoreViewEpoch&&restoreContext()===started,isOwner:()=>own===restoreEpoch&&restoreAccount()===account};}
 async function restorePublished(record,operation){let payload;try{payload=record?.delivery?await billing.readPublished(record):null;}catch(error){if(!operation.isCurrent())return false;throw error;}if(!operation.isCurrent())return false;return await onRestore(payload,record,{isCurrent:operation.isCurrent})!==false&&operation.isOwner();}
 let qrVersion=0,qrURL='',qrReadyURL='',qrLoading=null;
 function renderQR(url){
  const own=++qrVersion,canvas=$('.cloud-qr'),button=$('.cloud-qr-save'),message=$('.cloud-qr-status'),retry=$('.cloud-qr-retry');
  qrURL=url;qrReadyURL='';delete canvas.dataset.url;button.disabled=true;canvas.hidden=true;canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);retry.hidden=true;
  if(!url){message.textContent='';return;}
  try{if(typeof window.qrcode!=='function')throw Error('vendor');const q=window.qrcode(0,'M');q.addData(url);q.make();const size=q.getModuleCount(),unit=6;canvas.width=canvas.height=(size+8)*unit;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#000';for(let y=0;y<size;y++)for(let x=0;x<size;x++)if(q.isDark(y,x))ctx.fillRect((x+4)*unit,(y+4)*unit,unit,unit);if(own!==qrVersion)return;canvas.dataset.url=url;qrReadyURL=url;canvas.hidden=false;button.disabled=false;message.textContent='';}
  catch{message.textContent='Não foi possível gerar o QR Code. Você pode compartilhar o link ou tentar novamente.';retry.hidden=false;}
 }
 $('.cloud-qr-retry').addEventListener('click',async()=>{
  const own=qrVersion,url=qrURL;if(!url)return;const statusOwn=document.activeElement===$('.cloud-qr-retry');if(statusOwn)$('.cloud-qr-status').focus();$('.cloud-qr-retry').disabled=true;$('.cloud-qr-status').textContent='Preparando o QR Code…';
  try{if(typeof window.qrcode!=='function'){
   if(!qrLoading)qrLoading=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/assets/vendor/qrcode.js';script.onload=()=>{script.remove();resolve();};script.onerror=()=>{script.remove();reject(Error('vendor'));};document.head.append(script);}).finally(()=>{qrLoading=null;});
   await qrLoading;
  }if(own!==qrVersion||url!==current()?.delivery?.url)return;const restoreFocus=statusOwn&&document.activeElement===$('.cloud-qr-status');renderQR(url);if(restoreFocus){if(qrReadyURL===url)$('.cloud-qr-save').focus();else{$('.cloud-qr-retry').disabled=false;$('.cloud-qr-retry').focus();}}
  }catch{if(own===qrVersion){const restoreFocus=statusOwn&&document.activeElement===$('.cloud-qr-status');renderQR(url);if(restoreFocus){$('.cloud-qr-retry').disabled=false;$('.cloud-qr-retry').focus();}}}finally{$('.cloud-qr-retry').disabled=false;}
 });
 function guestContext(){return [getState().draftId,getState().format,current()?.id||'',billing.account?.email||'',billing.account?.authenticated===true].join(':');}
 function render(){const draftKey=getState().draftId+':'+getState().format;if(renderedDraft!==draftKey){chosen='';renderedDraft=draftKey;}trackRestoreContext();trackAccessContext();const record=current(),delivery=record?.delivery,consulting=!!chosen&&record?.id!==billing.find()?.id;const context=guestContext();if(guestView!==context){guestView=context;guestRenderEpoch++;$('.cloud-guest-list').replaceChildren();}$('.cloud-save-access').hidden=!record?.accessKey||!!record?.isAdmin||record?.sessionAuth===true;$('.cloud-access-description').textContent=record?.sessionAuth===true?'Esta compra está vinculada à sua conta. Para continuar em outro aparelho, entre em Minha conta com o mesmo e-mail. Você não precisa de um arquivo de acesso. Os rascunhos ainda não publicados ficam neste navegador.':'O arquivo de acesso permite editar e atualizar a compra. Guarde só para você. Para presentear alguém, envie o link do mimo ou o arquivo do presente.';panel.hidden=billing.config.mode==='offline';$('.cloud-environment').textContent=billing.config.mode==='test'?'Ambiente de teste. Os presentes publicados nesta etapa são de demonstração.':'';$('.cloud-result').hidden=!delivery;$('.cloud-guests').hidden=getState().format!=='convite'||record?.planId!=='celebrar'||!delivery||record.draftId!==getState().draftId;$('.cloud-edit-published').hidden=!delivery;$('.cloud-publish').disabled=busy||consulting;$('.cloud-publish').textContent=consulting?'Abra esta compra para editar antes de publicar':billing.find()?.delivery?'Atualizar meu presente publicado':'Publicar e criar meu link';const rows=billing.list().filter(r=>r.mode===billing.config.mode&&r.id);$('.cloud-purchase-label').hidden=!rows.length;$('.cloud-purchase-select').replaceChildren(...rows.map(r=>new Option((billing.config.plans?.[r.planId]?.title||'Compra')+' · '+r.id.slice(-6),r.id)));$('.cloud-purchase-select').value=record?.id||'';if(!delivery){renderQR('');return;}
  $('.cloud-link').value=delivery.url;$('.cloud-open').href=delivery.url;$('.cloud-expiry').textContent='Link disponível até '+new Date(delivery.expiresAt*1000).toLocaleDateString('pt-BR')+'. A cópia baixada continua com você.';renderQR(delivery.url);
 }
 billing.ready.then(render);document.addEventListener('billing:change',render);$('.cloud-purchase-select').addEventListener('change',event=>{chosen=event.target.value;render();});
 $('.cloud-publish').addEventListener('click',async()=>{if(busy)return;if(chosen&&current()?.id!==billing.find()?.id){status.textContent='Você está consultando outra compra. Abra a versão publicada para editar ou selecione a compra do rascunho atual.';return;}const context=()=>JSON.stringify([getState().draftId,getState().format,getState().purchaseId||'',chosen]),startedContext=context(),check=()=>{if(context()!==startedContext)throw Error('O presente em edição mudou. Confira a compra e publique novamente.');};let data=getData(),targetId=data.purchaseId||billing.find(data.draftId,data.format)?.id;if(!data.recipient?.trim()){status.textContent='Escreva para quem é o presente antes de publicar.';return;}busy=true;render();try{if(!await billing.requirePurchase(data.format,data.draftId,targetId)){status.textContent='Confirme a compra para publicar seu presente.';return;}check();targetId??=billing.find(data.draftId,data.format)?.id;status.textContent='Otimizando e preparando fotos, páginas e áudio…';await prepare();check();data={...structuredClone(getData()),purchaseId:targetId};const file=await makeDigitalGift(data,getAudio());check();const delivery=await billing.publish(data,file,progress=>{status.textContent='Enviando presente compactado · '+mediaSize(progress.bytes)+(progress.bytes<progress.original?' (antes '+mediaSize(progress.original)+')':'')+'…';});check();onPublished(data.purchaseId);chosen=billing.find(data.draftId,data.format,data.purchaseId).id;status.textContent='Seu mimo está publicado. Copie o link ou compartilhe o QR Code.';toast('Presente publicado!');render();if(data.format==='convite')await renderGuests();}catch(e){status.textContent=e.message;}finally{busy=false;render();}});
 $('.cloud-copy').addEventListener('click',async()=>{const value=$('.cloud-link');try{await navigator.clipboard.writeText(value.value);toast('Link do presente copiado.');}catch{value.focus();value.select();status.textContent='Selecione e copie o link acima.';}});
 $('.cloud-qr-save').addEventListener('click',()=>{const canvas=$('.cloud-qr'),url=current()?.delivery?.url;if(!url||qrReadyURL!==url||canvas.dataset.url!==url||canvas.hidden){renderQR(url||'');return;}try{const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='capimimo-qr-do-presente.png';a.click();}catch{qrReadyURL='';$('.cloud-qr-save').disabled=true;$('.cloud-qr-status').textContent='Não foi possível baixar o QR Code. Tente gerar novamente ou compartilhe o link.';$('.cloud-qr-retry').hidden=false;}});
 $('.cloud-save-access').addEventListener('click',()=>{const record=current();if(!record?.accessKey||record.isAdmin||record.sessionAuth===true){status.textContent=record?.isAdmin?'Abra seus testes pelo painel do administrador.':'Para acessar esta compra em outro aparelho, entre em Minha conta com o mesmo e-mail.';return;}downloadFile('capimimo-acesso-da-compra.json',billing.backup());});let accessInputOwner=null,accessView='',accessViewEpoch=0;const accessContext=()=>JSON.stringify([getState().draftId,getState().format,getState().purchaseId||'',chosen,billing.account?.email||'',billing.account?.authenticated===true]);function trackAccessContext(){const next=accessContext();if(next!==accessView){accessView=next;accessViewEpoch++;}}$('.cloud-restore-access').addEventListener('change',async event=>{const input=event.target,file=input.files[0];if(!file)return;trackAccessContext();const owner={},view=accessViewEpoch,started=accessContext(),current=()=>accessInputOwner===owner&&view===accessViewEpoch&&accessContext()===started;accessInputOwner=owner;try{status.textContent='Recuperando sua compra…';const records=await billing.restore(file);if(!current())return;chosen=records[0].id;render();$('.cloud-access').open=true;status.textContent='Acesso recuperado. Você pode abrir a versão publicada para editar.'+(records.skipped?' Algumas entradas antigas não puderam ser recuperadas.':'');}catch(e){if(current())status.textContent=e.message;}finally{if(accessInputOwner===owner){input.value='';accessInputOwner=null;}}});
 $('.cloud-edit-published').addEventListener('click',async()=>{if(busy)return;const record=current(),operation=beginRestore();busy=true;render();try{if(!await restorePublished(record,operation))return;status.textContent='Presente recuperado com fotos, áudio e personalização.';toast('Você já pode continuar editando.');}catch(e){if(operation.isCurrent())status.textContent=e.message;}finally{busy=false;render();}});
 async function renderGuests(){const list=$('.cloud-guest-list'),record=current(),context=guestContext(),epoch=++guestRenderEpoch;list.replaceChildren();let guests;try{guests=await billing.guests(record);}catch(error){if(epoch!==guestRenderEpoch||context!==guestContext())return;throw error;}if(epoch!==guestRenderEpoch||context!==guestContext())return;for(const guest of guests){const row=document.createElement('article'),name=document.createElement('strong'),text=document.createElement('p');name.textContent=guest.name;text.textContent=guest.status==='accepted'?guest.attendingCount+' presença(s) confirmada(s)':guest.status==='declined'?'Não poderá participar':'Aguardando resposta';row.append(name,text);const url=guest.url||(guest.linkRecovery==='unavailable'?'':billing.guestLink(guest.id,record));if(url){const button=document.createElement('button');button.type='button';button.textContent='Copiar convite';button.addEventListener('click',async()=>{if(context!==guestContext()||epoch!==guestRenderEpoch)return;try{await navigator.clipboard.writeText(url);toast('Convite individual copiado.');}catch{if(context===guestContext()&&epoch===guestRenderEpoch)status.textContent='Link do convite: '+url;}});row.append(button);const form=document.createElement('form'),label=document.createElement('label'),input=document.createElement('input'),send=document.createElement('button'),feedback=document.createElement('p');label.textContent='E-mail de '+guest.name;input.type='email';input.required=true;input.maxLength=254;input.autocomplete='off';input.placeholder='nome@exemplo.com';label.append(input);send.type='submit';send.textContent='Enviar convite por e-mail';feedback.setAttribute('role','status');form.append(label,send,feedback);let sending=false;form.addEventListener('submit',async event=>{event.preventDefault();if(sending||context!==guestContext()||epoch!==guestRenderEpoch||!form.reportValidity())return;const address=input.value.trim();if(!window.confirm('Enviar o convite de '+guest.name+' para '+address+'?'))return;sending=true;send.disabled=true;feedback.textContent='Enviando…';try{await billing.emailGuest(guest.id,address,record);if(context!==guestContext()||epoch!==guestRenderEpoch)return;input.value='';feedback.textContent='Convite aceito para envio. Peça à pessoa que confira a caixa de entrada e o spam.';}catch(error){if(context===guestContext()&&epoch===guestRenderEpoch)feedback.textContent=error.message;}finally{sending=false;send.disabled=false;}});row.append(form);}else{const note=document.createElement('p'),button=document.createElement('button');note.textContent=guest.linkRecovery==='unavailable'?'Não foi possível recuperar este link agora. Tente atualizar a lista. Gerar outro desativa o convite anterior e mantém a resposta.':'Este convite antigo não tem o link recuperável na conta. Gerar outro desativa o link anterior e mantém a confirmação recebida.';button.type='button';button.textContent='Gerar novo link';button.addEventListener('click',async()=>{if(context!==guestContext()||epoch!==guestRenderEpoch)return;button.disabled=true;button.textContent='Gerando…';try{await billing.regenerateGuestLink(guest.id,record);if(context!==guestContext())return;await renderGuests();status.textContent='Novo link gerado. O anterior foi desativado; a resposta foi preservada. Copie o convite para enviar.';}catch(error){if(context===guestContext())status.textContent=error.message;button.disabled=false;button.textContent='Gerar novo link';}});row.append(note,button);}list.append(row);}}
 const form=$('.cloud-guests form');form.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;busy=true;const button=form.querySelector('button'),record=current(),context=guestContext();button.disabled=true;try{await billing.addGuest(form.elements.guestName.value.trim(),Number(form.elements.guestCount.value),record);if(context!==guestContext())return;form.reset();await renderGuests();status.textContent='Convite individual criado. Copie o link para enviar à pessoa.';}catch(e){if(context===guestContext())status.textContent=e.message;}finally{busy=false;button.disabled=false;}});
 $('.cloud-guests').addEventListener('toggle',()=>{if($('.cloud-guests').open&&!$('.cloud-guests').hidden)renderGuests().catch(error=>status.textContent=error.message);});
 $('.cloud-refresh-guests').addEventListener('click',()=>renderGuests().catch(e=>status.textContent=e.message));$('.cloud-import-guests').addEventListener('click',async()=>{if(busy)return;busy=true;const record=current(),context=guestContext();try{const saved=await billing.guests(record);if(context!==guestContext())return;const names=new Set(saved.map(g=>g.name.trim().toLocaleLowerCase('pt-BR'))),guests=getState().guests||[];let count=0;for(const guest of guests){if(context!==guestContext())return;if(!guest.name?.trim()||names.has(guest.name.trim().toLocaleLowerCase('pt-BR')))continue;await billing.addGuest(guest.name,Math.min(10,Math.max(1,Number(guest.allowedCount)||1)),record);if(context!==guestContext())return;names.add(guest.name.trim().toLocaleLowerCase('pt-BR'));count++;}await renderGuests();status.textContent=count?count+' convite(s) individual(is) criado(s).':'Todos os convidados desta lista já têm um convite.';}catch(e){if(context===guestContext())status.textContent=e.message;}finally{busy=false;}});
 const recoverButton=document.createElement('button');recoverButton.type='button';recoverButton.className='header-library-button header-purchase-recovery';recoverButton.textContent='Recuperar compra';recoverButton.hidden=true;document.querySelector('.announcement').append(recoverButton);const recovery=document.createElement('dialog');recovery.className='purchase-recovery-dialog';recovery.setAttribute('aria-labelledby','purchase-recovery-title');recovery.innerHTML='<button type="button" class="purchase-recovery-close">Fechar</button><h2 id="purchase-recovery-title">Voltar ao seu mimo.</h2><p>Comprou pela sua conta? Entre com o mesmo e-mail para encontrar suas compras. Se comprou sem entrar, escolha uma compra deste aparelho ou importe o arquivo de acesso que você guardou.</p><button type="button" class="recovery-open-account">Entrar em Minha conta</button><label>Arquivo de acesso da compra sem login<input type="file" accept="application/json,.json"></label><p class="recovery-status" role="status"></p><div class="recovery-list"></div>';document.body.append(recovery);const recoveryStatus=recovery.querySelector('.recovery-status');let recoveryEpoch=0,recoveryInputOwner=null;
 const accessExpired=record=>record?.expired===true||(Number.isFinite(record?.expiresAt)&&record.expiresAt*1000<=Date.now());
 function recoverList(){recoveryEpoch++;const list=recovery.querySelector('.recovery-list');list.replaceChildren();const records=billing.list().filter(row=>row.mode===billing.config.mode&&row.id);if(!records.length)recoveryStatus.textContent='Para uma compra vinculada ao seu e-mail, entre em Minha conta. Se comprou sem entrar, importe seu arquivo capimimo-acesso-da-compra.json.';for(const item of records){const row=document.createElement('article'),title=document.createElement('strong'),button=document.createElement('button');title.textContent=(billing.config.plans?.[item.planId]?.title||'Compra')+' · '+item.id.slice(-6);button.type='button';button.textContent=accessExpired(item)?'Período encerrado · ver orientação':item.status==='approved'?(item.delivery?'Abrir presente publicado':'Continuar criando'):'Ver situação da compra';row.append(title,button);button.addEventListener('click',async()=>{const own=++recoveryEpoch,current=()=>own===recoveryEpoch&&recovery.open;button.disabled=true;try{const record=billing.get(item.id);await billing.refresh(record,true);if(!current())return;if(accessExpired(record)){button.textContent='Período encerrado · ver orientação';recoveryStatus.textContent='O período de 12 meses desta compra terminou. Sua cópia baixada continua com você e seu rascunho atual não foi apagado. Para criar outro presente, feche esta janela e escolha um novo plano.';return;}if(record.status==='approved'){const payload=record.delivery?await billing.readPublished(record):null;if(!current())return;if(await onRestore(payload,record,{isCurrent:current})===false||!current())return;chosen=record.id;recovery.close();render();}else{button.textContent='Verificar pagamento novamente';recoveryStatus.textContent=record.status==='pending'||record.status==='preparing'?'O pagamento ainda não foi confirmado. Se você já pagou, aguarde alguns instantes e toque em verificar novamente. Seu rascunho atual continua aqui.':record.status==='revoked'?'Esta compra foi cancelada ou reembolsada. Seu rascunho atual foi preservado. Se precisar de ajuda, fale com bacochinakawai@gmail.com.':'O pagamento não foi aprovado. Seu rascunho atual foi preservado. Para ajuda com esta compra, fale com bacochinakawai@gmail.com.';}}catch(e){if(current())recoveryStatus.textContent=e.message;}finally{button.disabled=false;}});list.append(row);}}
 recovery.querySelector('.recovery-open-account').addEventListener('click',()=>{const trigger=document.querySelector('.customer-account-trigger');if(!trigger){recoveryStatus.textContent='A entrada da conta está carregando. Tente novamente em instantes.';return;}recoveryEpoch++;recovery.close();trigger.click();});
 recoverButton.addEventListener('click',()=>{recoveryStatus.textContent='';recoverList();recovery.showModal();});recovery.querySelector('.purchase-recovery-close').addEventListener('click',()=>{recoveryEpoch++;recovery.close();});recovery.addEventListener('cancel',()=>{recoveryEpoch++;});recovery.addEventListener('close',()=>{if(!recovery.open)recoveryEpoch++;});recovery.querySelector('input').addEventListener('change',async event=>{const input=event.target,file=input.files[0];if(!file)return;const owner={},own=++recoveryEpoch,current=()=>own===recoveryEpoch&&recovery.open;recoveryInputOwner=owner;try{recoveryStatus.textContent='Recuperando sua compra…';const restored=await billing.restore(file);if(!current())return;recoveryStatus.textContent='Compra recuperada. Escolha o presente abaixo.'+(restored.skipped?' Algumas entradas antigas não puderam ser recuperadas.':'');recoverList();}catch(e){if(current())recoveryStatus.textContent=e.message;}finally{if(recoveryInputOwner===owner){input.value='';recoveryInputOwner=null;}}});billing.ready.then(()=>recoverButton.hidden=billing.config.mode==='offline');
 async function openOrder(record){const operation=beginRestore();try{await billing.refresh(record,true);}catch(error){if(!operation.isCurrent())return false;throw error;}if(!operation.isCurrent())return false;if(accessExpired(record))throw Error('O período de acesso terminou. Use sua cópia baixada ou crie outro presente.');if(record.status!=='approved')throw Error(record.status==='pending'?'Pagamento ainda não confirmado. Aguarde e verifique novamente.':'Esta compra não está disponível para edição.');if(!await restorePublished(record,operation))return false;chosen=record.id;render();return true;}
 return{openOrder,render,restore:record=>restorePublished(record,beginRestore())};
}
